import { SelectTab } from '@cetus/design'
// import { useDebounceFunction } from '@cetus/hooks'
import { CoinInfo } from '@cetus/types'
import { Heading, Modal, ModalBody, ModalCloseButton, ModalContent, ModalHeader, ModalOverlay } from '@chakra-ui/react'
import { useState } from 'react'
import CollectListBox from './CollectListBox'
import { SearchInput } from './SearchInput'
import TokenList from './TokenList'

type TokenSelectModalProps = {
  tokenInfo?: CoinInfo
  isOpen: boolean
  onClose: () => void
  onSelectToken: (tokenInfo: CoinInfo) => void
}
export default function TokenSelectModal(props: TokenSelectModalProps) {
  const { isOpen, onClose, onSelectToken } = props

  const [inputValue, setInputValue] = useState('')
  const changeInputValue = (value: string) => {
    setInputValue(value)
  }
  const selectToken = (tokenInfo: CoinInfo) => {
    onSelectToken(tokenInfo)
    onClose()
  }
  const tabList = [
    {
      label: 'Default',
      value: 'Default'
    },
    {
      label: 'Imported',
      value: 'Imported'
    }
  ]

  const labelList = [
    {
      label: 'All',
      value: 'All'
    },
    {
      label: 'Native',
      value: 'Native'
    },
    {
      label: 'Wormhole',
      value: 'Wormhole'
    },
    {
      label: 'Celer',
      value: 'Celer'
    }
  ]

  const [currentTab, setCurrentTab] = useState('Default')
  const [currentLabel, setCurrentLabel] = useState('All')
  return (
    <Modal isOpen={isOpen} onClose={onClose}>
      <ModalOverlay />
      <ModalContent minWidth={482}>
        <ModalHeader>
          <Heading fontWeight="500" fontSize="16px">
            Select a token
          </Heading>
        </ModalHeader>
        <ModalCloseButton />
        <ModalBody pb="30px" textAlign="center">
          <SearchInput inputValue={inputValue} changeInputValue={e => changeInputValue(e)} />
          <CollectListBox onSelectToken={(tokenInfo: CoinInfo) => selectToken(tokenInfo)} />
          <SelectTab
            type="borderTab"
            wrapStyle={{
              w: {
                base: '100%',
                lg: '395px'
              },
              h: '48px',
              bg: 'none',
              border: 'none'
            }}
            itemStyle={{
              // w: '50%',
              marginRight: '40px',
              fontSize: '16px'
            }}
            tabList={tabList}
            currentTab={currentTab}
            handleChangeTab={item => {
              setCurrentTab(item.value)
            }}
          />
          <SelectTab
            type="outlineTab"
            wrapStyle={{
              w: {
                base: '100%'
              },
              h: '48px',
              padding: '4px',
              marginTop: '16px'
            }}
            itemStyle={{
              w: '25%',
              // marginRight: '40px',
              fontSize: '16px',
              borderRadius: '8px'
            }}
            tabList={labelList}
            currentTab={currentLabel}
            handleChangeTab={item => {
              setCurrentLabel(item.value)
            }}
          />
          <TokenList onSelectToken={(tokenInfo: CoinInfo) => selectToken(tokenInfo)} />
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}
